solution.solution.cpp:
#include <string>

bool isDecorated(const std::string& symbol)
{
    return !symbol.empty() && symbol[0] == '?';
}

unitTests:
TEST("C++ names") { CHECK(isDecorated("?add@@YAHHH@Z")); CHECK(isDecorated("?x")); }
TEST("C names") { CHECK(!isDecorated("stackHeight")); CHECK(!isDecorated("_area@8")); CHECK(!isDecorated("@f@8")); }
TEST("empty") { CHECK(!isDecorated("")); }

